package actionauth

import (
	"context"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/butler/butler/internal/budget"
)

// The proof is generated by the actual owning journal reviewer, then consumed
// by the actual budget guard. A terminal classification or a new Input alone
// must not erase external uncertainty or create any execution authority.
func TestOwnerOutcomeReviewedPreparationBudgetRequiresCompleteNoWriteProofIntegration(t *testing.T) {
	for _, mode := range []string{"valid", "no_proof", "wrong_source", "wrong_digest", "same_run", "old_live", "input_live", "stop_uncertain", "wrong_policy", "dispatch_executing", "grant_authorized", "other_unknown", "credential"} {
		t.Run(mode, func(t *testing.T) {
			pool, b := stoppedLocalFixture(t, true, func(b *ActionBinding) {
				b.ToolName = "browser.prepare_fill"
				b.ContractHash = stoppedLocalFillContract
				b.ContractRevision = "2"
				b.Effect = EffectPrepare
				b.Resource = "browser:context:https://example.com/form"
				if mode == "credential" {
					b.CredentialRefs = []CredentialRef{{Alias: "private", Field: "password"}}
				}
			})
			ctx := context.Background()
			if _, err := pool.Exec(ctx, `ALTER TABLE tasks ADD COLUMN parent_task_id TEXT`); err != nil {
				t.Fatal(err)
			}
			raw, err := os.ReadFile(filepath.Join("..", "..", "migrations", "037_execution_budgets.up.sql"))
			if err != nil {
				t.Fatal(err)
			}
			if _, err = pool.Exec(ctx, string(raw)); err != nil {
				t.Fatal(err)
			}
			p := EffectPolicy{RetrySafety: "unsafe", VerificationMethod: "local_browser_preparation_v1", LocalPreparation: &LocalPreparationBinding{SessionID: "context", ExpectedURL: "https://example.com/form", ObservationVersion: 1}}
			raw, _ = json.Marshal(p)
			if _, err = pool.Exec(ctx, `UPDATE action_effects SET policy=$1`, raw); err != nil {
				t.Fatal(err)
			}
			raw, _ = json.Marshal(Grant{ID: "old-grant", Binding: b, State: "authorized"})
			if _, err = pool.Exec(ctx, `UPDATE action_authorizations SET grant_data=$1`, raw); err != nil {
				t.Fatal(err)
			}
			if mode != "no_proof" && mode != "wrong_source" && mode != "wrong_digest" {
				tx, err := pool.Begin(ctx)
				if err != nil {
					t.Fatal(err)
				}
				_, err = ReviewStoppedLocalTx(ctx, tx, "input")
				if err != nil {
					tx.Rollback(ctx)
					t.Fatal(err)
				}
				if err = tx.Commit(ctx); err != nil {
					t.Fatal(err)
				}
			} else if mode != "no_proof" {
				const method = "pinned_preparation_no_write_v1"
				proof := EffectEvidence{EvidenceID: "evidence_" + digest(b.ActionID+"\x00"+method), ActionID: b.ActionID, SourceActionID: b.ActionID, SourceRunID: b.RunID, SourceToolCallID: b.ToolCallID, Source: "owning_local_preparation_contract", Method: method, Verdict: StateUnknown, ResultDigest: digest(b.ActionID + "\x00" + stoppedLocalFillContract + "\x00no_write_local_result_unknown")}
				proof.ObservedAt = time.Now().UTC()
				proof.RecordedAt = proof.ObservedAt
				if mode == "wrong_source" {
					proof.Source = "model_report"
				} else {
					proof.ResultDigest = digest("invented")
				}
				tx, err := pool.Begin(ctx)
				if err != nil {
					t.Fatal(err)
				}
				if err = insertEvidence(ctx, tx, proof); err != nil {
					tx.Rollback(ctx)
					t.Fatal(err)
				}
				if err = tx.Commit(ctx); err != nil {
					t.Fatal(err)
				}
			}
			if _, err = pool.Exec(ctx, `UPDATE input_stopped_attempts SET classification='known';INSERT INTO runs(run_id,task_id,task_revision,session_key,input_event_id,current_state,status) VALUES('next',NULL,NULL,'web:owner','new-event','tool_running','tool_running')`); err != nil {
				t.Fatal(err)
			}
			current := "next"
			var mutation string
			switch mode {
			case "same_run":
				current = "run"
			case "old_live":
				mutation = `UPDATE session_ownership SET lease_id='old-live',expires_at=clock_timestamp()+interval '1 hour'`
			case "input_live":
				mutation = `UPDATE accepted_inputs SET claim_id='old-live',claim_expires_at=clock_timestamp()+interval '1 hour'`
			case "stop_uncertain":
				mutation = `UPDATE input_stopped_attempts SET classification='uncertain'`
			case "wrong_policy":
				mutation = `UPDATE action_effects SET policy=jsonb_set(policy,'{verification_method}','"none"')`
			case "dispatch_executing":
				mutation = `UPDATE action_effect_dispatches SET outcome='executing'`
			case "grant_authorized":
				mutation = `UPDATE action_authorizations SET state='authorized'`
			case "other_unknown":
				mutation = `INSERT INTO action_effects(action_id,fingerprint,initial_binding,policy,state) VALUES('other','other','{"owner_id":"owner","task_id":"","run_id":"run","tool_name":"browser.click","effect":"unknown"}','{}','effect_unknown')`
			}
			if mutation != "" {
				if _, err = pool.Exec(ctx, mutation); err != nil {
					t.Fatal(err)
				}
			}
			tx, err := pool.Begin(ctx)
			if err != nil {
				t.Fatal(err)
			}
			defer tx.Rollback(ctx)
			c := budget.NewController(pool, budget.DefaultPolicy())
			err = c.CheckToolTx(ctx, tx, budget.ToolIdentity{RunID: current, ToolName: "browser.prepare_fill", Effect: "prepare", ContractHash: "new-reviewed-contract", ArgsHash: "new-ordinary-proposal"})
			var loop *budget.LoopError
			if mode == "valid" {
				if err != nil {
					t.Fatal("complete no-write evidence did not qualify normal policy", err)
				}
			} else if !errors.As(err, &loop) {
				t.Fatal("unknown/foreign/incomplete evidence did not retain loop guard", mode, err)
			}
			tx.Rollback(ctx)
			e, err := NewPostgresStore(pool).GetEffect(ctx, b.ActionID)
			if err != nil || e.State != StateUnknown {
				t.Fatal("budget guard rewrote old local outcome", err)
			}
		})
	}
}
